export interface SpriteSlice {
  id: string;
  name?: string;
  groupId: string;
  groupOrder: number;
  x: number;
  y: number;
  width: number;
  height: number;
  color?: string;
}

export interface GlyphSlot {
  x: number;
  y: number;
  width: number;
  height: number;
  advanceX?: number;
}

export interface FontCharMapping {
  id: string;
  chars: string;
  small?: GlyphSlot | null;
  big?: GlyphSlot | null;
}

export interface FontGlyph {
  char: string;
  codepoint: number;
  x: number;
  y: number;
  width: number;
  height: number;
  advanceX: number;
}

export type ScreenSetupType = 'split' | 'split-dongle' | 'dongle-only' | 'custom';

export interface LayoutBlock {
  id: string;
  widgetType?: string;
  instanceId?: string;
  name: string;
  x?: number;
  y: number;
  width?: number;
  height: number;
  enabled: boolean;
  description?: string;
  side?: 'left' | 'right' | 'dongle' | string;
}

export interface DisplaySettings {
  rotation: '90' | '270';
  invert: boolean;
  idleTimeoutMs: number;
  screenOffTimeoutMs?: number;
  idleScreensEnabled?: boolean;
  userName: string;
  repoOwner: string;
  repoName: string;
  branch: string;
  githubToken: string;
}

